package dev.konqasasas.beat.domain.endurance;
import dev.konqasasas.beat.domain.*;import dev.konqasasas.beat.domain.ranking.*;import java.util.*;
public final class EnduranceSession {private final Map<UUID,State> players=new LinkedHashMap<>();public EnduranceSession(Map<UUID,String> names,EnduranceRules rules){names.forEach((id,name)->players.put(id,new State(new Competitor(id,name),new EnduranceRecord(rules))));}public void activate(UUID id){State s=req(id);if(!s.record.frozen()){s.active=true;s.competitor.markParticipated(CompetitionKind.ENDURANCE);}}public Update reach(UUID id,int progress,long tick){State s=requireActive(id);int oldRank=rank(id);boolean z2=s.record.zone2Reached(),z3=s.record.zone3Reached(),goal=s.record.goalReached();var update=s.record.reachProgress(progress,tick);return new Update(update,oldRank,rank(id),!z2&&s.record.zone2Reached(),!z3&&s.record.zone3Reached(),!goal&&s.record.goalReached());}public List<Elimination> eliminateWithoutZone(int zone){List<Elimination> out=new ArrayList<>();for(var e:rankings()){State s=req(e.competitor().uuid());boolean reached=zone==2?s.record.zone2Reached():s.record.zone3Reached();if(s.active&&!reached){s.active=false;s.record.freeze();out.add(new Elimination(e.competitor().uuid(),e.rank(),s.record.maxProgress()));}}return List.copyOf(out);}public int zone(UUID id){var r=req(id).record;return r.zone3Reached()?3:r.zone2Reached()?2:1;}public void finish(){players.values().forEach(s->{s.active=false;s.record.freeze();});}public List<RankedEntry<EnduranceRecord>> rankings(){return CompetitionRankings.endurance(players.values().stream().map(s->new RankingEntry<>(s.competitor,s.record)).toList());}public int rank(UUID id){return rankings().stream().filter(e->e.competitor().uuid().equals(id)).findFirst().orElseThrow().rank();}public boolean active(UUID id){return req(id).active;}public boolean contains(UUID id){return players.containsKey(id);}public EnduranceRecord record(UUID id){return req(id).record;}public Competitor competitor(UUID id){return req(id).competitor;}private State requireActive(UUID id){State s=req(id);if(!s.active||s.record.frozen())throw new IllegalStateException("player is not active");return s;}private State req(UUID id){State s=players.get(id);if(s==null)throw new IllegalArgumentException("unknown player");return s;}public record Update(EnduranceRecord.ProgressUpdate progress,int previousRank,int currentRank,boolean zone2,boolean zone3,boolean goal){public boolean rankChanged(){return progress.changed()&&previousRank!=currentRank;}}public record Elimination(UUID id,int rank,int progress){}private static final class State{final Competitor competitor;final EnduranceRecord record;boolean active;State(Competitor c,EnduranceRecord r){competitor=c;record=r;}}}
